      <select
        multiple
        value={selectedTopics}
        onChange={(event) => handleTopicSelect(event.target.value)}
      >
        {topics.map((topic) => (
          <option key={topic.id} value={topic.name}>
            {topic.name}
          </option>
        ))}
      </select>
      <br />
      <br />
      {selectedTopics.map((topic) => (
        <div key={topic}>
          <label>{topic}</label>
          <br />
