function simulatePendulum(initialAngle, initialVelocity) {
  let angle = initialAngle;
  let velocity = initialVelocity;
  let acceleration = 9.81; // gravity
  let timeStep = 0.01; // seconds
  let time = 0; // seconds

  // Draw the pendulum
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 50, 0, Math.PI);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Simulate the pendulum motion
  function updatePendulum() {
    // Calculate the new angle and velocity
    velocity += acceleration * timeStep;
    angle += velocity * timeStep;

    // Draw the pendulum
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(canvas.width / 2, canvas.height / 2 - 50 * Math.sin(Math.PI / 180 * angle), 50, 0, Math.PI);
    ctx.strokeStyle = 'black';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Check if the pendulum has stopped
    if (Math.abs(velocity) < 0.01) {
      clearInterval(interval);
    }

    // Update the time
    time += timeStep;
  }

  const interval = setInterval(updatePendulum, timeStep * 1000);
}

// Start the simulation
